"""Renders data/timing-summary.md from data/timing.json and data/grid-verification.json (stdlib only)."""
import json, sys, re, difflib
from pathlib import Path
sys.stdout.reconfigure(encoding="utf-8")
R = str(Path(__file__).resolve().parents[2] / "data") + "/"
T = json.load(open(R + "timing.json", encoding="utf-8")); V = json.load(open(R + "grid-verification.json", encoding="utf-8"))
ts = lambda t: "-" if t is None else "%d:%04.1f" % (int(t // 60), t % 60)
S = T["sections"]; Ls = T["lines"]; Ws = T["words"]; tp = T["tempo"]; FPS = T["fps"]
norm = lambda w: re.sub(r"[^a-z0-9]", "", w.lower())
sim = lambda a, b: 1.0 if a == b else difflib.SequenceMatcher(None, a, b).ratio()
sec_at = lambda t: next((s["name"] for s in S if s["start"] <= t < s["end"]), "-")
o = []
o.append("# Vorathul Nerfed - timing summary\n")
o.append("Generated by tools/timing/*.py from `audio/Vorathul.Nerfed.wav` (%.2f s, %d fps = %d frames). Every number below comes from a run on that file; the style prompt in `sarki/sozler.md` was treated as a claim to measure. Machine data: `data/timing.json`; a listening pass by a model (opinion, not measurement) is in `data/listening-notes.md`.\n" % (T["duration"], FPS, round(T["duration"] * FPS)))

# ---- tempo
g = tp["grid_segments"]; main = [x for x in g if 185.0 <= x["bpm"] <= 186.6]
o.append("## Tempo and grid\n")
o.append("- **'About 170 bpm' is not what the audio does.** The locked parts of the song pulse at 186.2-186.5 BPM (period ~0.322 s), about 9 %% above the claim; none of the 11 per-segment fits settles at 170 (the slowest are 165.8 in Announcer 2, 176.6 in the interlude and 179.5-181.6 elsewhere). The level is ambiguous by a factor of two: a straight-grid onset comb (mean-normalised onset envelope) scores %.3f at the half-time level (%.1f BPM) vs %.3f at the pulse level (%.1f BPM) and %.3f at double time (%.1f BPM), so a musician could count this as 93 BPM with 2.6 s bars. This file uses the ~186 BPM pulse as 'beat' and 4 beats (~1.29 s) as 'bar'; a half-time bar is two of these. %d of %d grid segments (%.0f s of %.0f s) sit at 185-186.5 BPM." % (T["octave_check"]["half_time"]["score"], T["octave_check"]["half_time"]["bpm"], T["octave_check"]["pulse"]["score"], T["octave_check"]["pulse"]["bpm"], T["octave_check"]["double_time"]["score"], T["octave_check"]["double_time"]["bpm"], len(main), len(g), sum(x["end"] - x["start"] for x in main), T["duration"]))
o.append("- **The tempo does change.** Grid segments (each fitted with its own constant period and phase by dynamic programming; boundaries are +-0.5 s):\n")
o.append("| segment | BPM | period s | what it is |"); o.append("|---|---|---|---|")
for x in g:
    names = ", ".join(s["name"] for s in S if s["start"] < x["end"] - 1.0 and s["end"] > x["start"] + 1.0)
    o.append("| %s - %s | %.2f | %.4f | %s |" % (ts(x["start"]), ts(x["end"]), x["bpm"], x["period"], names))
o.append("")
o.append("  The slow stretches are: Announcer 1 (%s, 179.5 BPM), Announcer 2 (%s, 165.8 BPM), Soft Interlude + start of Build (%s, 176.6 BPM) and the closing Announcer 3 / Choir / Outro (%s, 181.6 BPM). Announcer-section values rest on few and weak onsets (grid lock there is poor, median |onset-grid| 18-26 ms), so read them as 'slower or unclear', not as exact. The interlude value (176.6 from the grid, 176.7 from an independent comb on that section only) is the best supported slowdown: -5.3 %% against 186.4." % (ts(g[3]["start"]), ts(g[5]["start"]), ts(g[7]["start"]), ts(g[10]["start"])))
o.append("- A single constant BPM would be wrong by seconds: use `beats[]` / `downbeats[]` from timing.json, never `bpm`. Fitted beats: %d; bars: %d (%d bars are not 4 beats long, listed in `tempo.odd_bars`: %s)." % (tp["beats_total"], tp["bars"], len(tp["odd_bars"]), ", ".join("bar %d at %s (%d beats)" % (b["bar"], ts(b["t"]), b["beats"]) for b in tp["odd_bars"])))
o.append("- Structure check (bars x 4 x beat period vs segment length, `data/grid-verification.json`): diff in beats per segment = %s. Most are within +-1 beat; 146.8-171.7 s is -3.0 and 243.4-273.8 s is +4.3 beats (the end has a fade and the bars there are least certain)." % ", ".join("%+.1f" % r["diff_beats"] for r in V["equation_per_segment"]))
o.append("- Grid accuracy: onset-snapped beats vs grid: median |dev| %.1f ms, max %.1f ms, %d of %d beats beyond 1 frame (33.3 ms). Locked sections (e.g. 30-79 s, 93-137 s, 197-243 s) have median |dev| 3-5 ms; the intro (0-30 s, organ + choir) and the announcer sections are the loosest." % (tp["onset_residual_ms"]["median_abs"], tp["onset_residual_ms"]["max"], tp["onset_residual_ms"]["n_over_one_frame"], tp["onset_residual_ms"]["n"]))
o.append("- Downbeat (bar line) phase is the weakest part of the grid: chord changes are strongest on the chosen bar start in only %d of %d sections and kick-band onsets in %d of %d (the kicks are double-kick, so 'nearest beat' is ambiguous: window medians %+.0f to %+.0f ms). Use beats for frame sync; treat bar numbers as +-1 beat." % (V["phase0_wins"]["chord_change"], V["phase0_wins"]["sections"], V["phase0_wins"]["kick"], V["phase0_wins"]["sections"], min(r["median_ms"] for r in V["kick_vs_beat_per_30s"]), max(r["median_ms"] for r in V["kick_vs_beat_per_30s"])))
o.append("")

# ---- sections
o.append("## Sections (bar-snapped, from lyric alignment + energy steps)\n")
o.append("| # | section | start - end | bars (n) | BPM grid / comb | key (best, r) | mean dB | band dB | notes |")
o.append("|---|---|---|---|---|---|---|---|---|")
for i, s in enumerate(S):
    t = s["tempo"]; tag = ("voice tags: " + ", ".join(s["voice_tags"]) + "; ") if s["voice_tags"] else ""
    o.append("| %d | %s | %s - %s | %d-%d (%d) | %s / %s | %s (%.2f) | %.1f | %.1f | %sstart: %s |" % (i + 1, s["name"], ts(s["start"]), ts(s["end"]), s["start_bar"], s["end_bar"], s["n_bars"],
             t["bpm_fitted_grid"] or "-", t["bpm_onset_comb"] or "-", s["key"]["best"], s["key"]["r"], s["mean_db"], s["mean_band_db"], tag, s["start_rule"]))
o.append("\nmean dB = RMS of the whole mix per bar, averaged; band dB = RMS of the accompaniment stem (htdemucs, no vocals; the song's median is %.1f dB). Sections with 1-3 bars (Scream 1, Outro) have a comb tempo of '-' because the section is too short (< 5 s). Where grid and comb disagree by more than 3 %% (Pre-Chorus: 186.4 vs 162.2, 6 s long) the section is too short for the comb; the grid value is the neighbouring locked grid." % T["band_median_db"])
o.append("Section edges are bar lines; vocal-led sections start at the downbeat at/before the first sung word + 0.5 s, so a start can be one bar off from where a musician would count it. The Intro (0-49 s) is long: choir chant 'Vo-ra-thul' is heard at 3.5 s and 12.1 s, then instruments without sung words until Verse 1 at 49.5 s.\n")
o.append("Voice-tag lines (Verse 2): lines tagged growled/operatic are anchored, but the pitch tracker returned no usable f0 for them (growl and layered choir), so **growl vs operatic is not measured**, only the tags from the sheet are carried.\n")

# ---- lines
o.append("## Lines vs the lyric sheet (anchored = at least half of the words matched to measured words)\n")
o.append("| section | tag | start | end | match | text / what whisper heard |"); o.append("|---|---|---|---|---|---|")
for L in Ls:
    txt = L["text"].replace("|", "/")
    if L["matched_words"] < L["n_words"] and L["heard"]: txt += " -> heard: " + L["heard"] + " (unmatched: " + ", ".join(L["unmatched_lyric_words"]) + ")"
    elif L["matched_words"] == 0: txt += " -> nothing matched"
    o.append("| %s | %s | %s | %s | %d/%d | %s |" % (L["section"], L["voice_tag"] or "-", ts(L["start"]), ts(L["end"]), L["matched_words"], L["n_words"], txt))
na = sum(L["anchored"] for L in Ls)
o.append("\nAnchored lines: **%d/%d**; every lyric word matched: %d/%d. Heard but not in the sheet: %s.\n" % (na, len(Ls), sum(L["matched_words"] == L["n_words"] for L in Ls), len(Ls),
         "; ".join("%s-%s \"%s\"" % (ts(e["start"]), ts(e["end"]), e["text"]) for e in T["heard_not_in_lyrics"]) or "nothing"))
o.append("Intro whisper heard 'VORASOL' for 'Vo-ra-thul' at 3.5 s and 12.1 s (a clipped pass over 0-50 s also produced a 'Thanks for watching!' at 33.3 s, a hallucination on instrumental audio, ignored). The final VO-RA-THUL chants (248-270 s) are heard as 'Våra Tull' by the mix pass and as 'Vorathul' only by the vocal-stem pass.\n")

# ---- stops
o.append("## Stops and drop-outs\n")
ann_ = [s_ for s_ in S if s_["name"].startswith("Announcer")]
dd = [T["band_median_db"] - s_["mean_band_db"] for s_ in ann_]
o.append("There is **no stretch where everything is silent for more than about half a second** (apart from the file start and end). What exists: (1) a few hard gaps (whole mix under -40 dB or 12 dB under its local level, >= 0.2 s) and (2) windows where the accompaniment stem is 10 dB or more under the song's median band level (%.1f dB; threshold %.1f dB) for >= 1 s, i.e. the band is gone or very thin while a voice stays. Under the announcer the band stem sits at %.1f to %.1f dB, i.e. %.0f-%.0f dB under the median (this may include some robot-voice leakage into the stem, so 'band thinned a lot' is the measured fact, 'band absent' is not). Rows at 0:00 and 4:32+ are the file's own start and end.\n" % (T["band_median_db"], T["band_median_db"] - 10, min(s_["mean_band_db"] for s_ in ann_), max(s_["mean_band_db"] for s_ in ann_), min(dd), max(dd)))
o.append("| start | end | dur s | section | kind | mix dB | band dB | vocal dB | words heard |"); o.append("|---|---|---|---|---|---|---|---|---|")
for s_ in T["stops"]:
    kind = "gap" if s_["kind"].startswith("gap") else ("band down, voice audible" if s_.get("voice_audible") else "band down, no voice")
    o.append("| %s | %s | %.1f | %s | %s | %.1f | %.1f | %.1f | %s |" % (ts(s_["start"]), ts(s_["end"]), s_["dur"], sec_at(s_["start"]), kind, s_["mix_db"], s_["band_db"], s_["vocal_db"], s_["words"] or "-"))
o.append("")
ann = [s for s in S if s["name"].startswith(("Announcer", "Scream"))]
o.append("Announcer and scream sections, mean levels (dB): " + "; ".join("%s %s-%s mix %.1f / band %.1f / vocal %.1f" % (s["name"], ts(s["start"]), ts(s["end"]), s["mean_db"], s["mean_band_db"], s["mean_vocal_db"]) for s in ann) + ".")
gap_ = max((x for x in T["stops"] if x["kind"].startswith("gap") and 2.0 < x["start"] < 270.0), key=lambda x: -x["mix_db"])        # the deepest gap
sc1 = next(s_ for s_ in S if s_["name"] == "Scream 1"); sc2 = next(s_ for s_ in S if s_["name"] == "Scream 2")
o.append("Reading: the only clean near-silence inside the song is **%.1f-%.1f s** (mix %.1f dB, %.1f s), right before the first robot 'Patch two point three' (the vocal-stem pass hears 'Patch' at 79.1 s). Announcer 1 runs from the pre-chorus drop (band thinning from ~71.4 s) to the scream; Announcer 2 starts with the band thinning at 137.9 s; Announcer 3 at 245.4 s. Scream 1 (UNFAIR, %.1f s) has band level %.1f dB, so it is nearly unaccompanied; Scream 2 (MY THEME SONG, 147.6 s) has band %.1f dB, so partly accompanied. The band is back at full level (about -24 dB) at the chorus downbeats %s and %s. Whether the voice is a 'robot' cannot be told from the stems.\n" % (
    gap_["start"], gap_["end"], gap_["mix_db"], gap_["dur"], 98.76, sc1["mean_band_db"], sc2["mean_band_db"], ts(next(s_ for s_ in S if s_["name"] == "Chorus 1")["start"]), ts(next(s_ for s_ in S if s_["name"] == "Chorus 2")["start"])))

# ---- gag words
def find_all(tokens, thr=0.72, maxskip=1):
    """every run of measured words matching the tokens in order, with at most maxskip foreign words between consecutive tokens"""
    out = []; toks = [norm(t) for t in tokens]; n = len(Ws); i = 0
    while i < n:
        if sim(toks[0], norm(Ws[i]["w"])) >= thr:
            hit = [i]
            for k in range(1, len(toks)):
                q = next((q for q in range(hit[-1] + 1, min(n, hit[-1] + 2 + maxskip)) if sim(toks[k], norm(Ws[q]["w"])) >= thr), None)
                if q is None: break
                hit.append(q)
            if len(hit) == len(toks) or (len(toks) > 2 and len(hit) >= len(toks) - 1): out.append((hit, len(hit) == len(toks))); i = hit[-1] + 1; continue
        i += 1
    return out
GAGS = [("health reduced by forty percent", "health reduced by forty percent", "Vorathul: health reduced"), ("Meteor Rain: removed", "meteor rain removed", "Meteor"), ("Phase three: removed", "phase three removed", "Phase three"),
        ("UNFAIR (announcer line and scream)", "unfair", "UNFAIR"), ("beat me with a shoe", "beat me with a shoe", "beat me with a shoe"), ("They took my wings", "they took my wings", "They took my wings"),
        ("My second form", "my second form", "My second form"), ("My laser eyes", "my laser eyes", "My laser eyes"), ("My cursed storm", "my cursed storm", "My cursed storm"), ("seven minutes long", "seven minutes long", "seven minutes"),
        ("skips it", "skips it", "skips it"), ("can now be skipped", "can now be skipped", "can now be skipped"), ("volume reduced", "volume reduced", "volume reduced"), ("MY THEME SONG", "my theme song", "MY THEME SONG"),
        ("built to be loved", "built to be loved", "built to be loved"), ("By being hated", "by being hated", "By being hated"), ("changes reverted", "changes reverted", "changes reverted")]
o.append("## Gag-word anchors (measured whisper words; times are word starts / ends in seconds, frame at %d fps)\n" % FPS)
o.append("| phrase | start | end | frame | section | heard as | status |"); o.append("|---|---|---|---|---|---|---|")
for label, phrase, linekey in GAGS:
    res = find_all(phrase.split())
    if label.startswith("UNFAIR"): res = find_all(["unfair"], 0.85)
    if res:
        for hit, full in res:
            a, z = Ws[hit[0]], Ws[hit[-1]]
            o.append("| %s | %.2f | %.2f | %d | %s | %s | %s |" % (label, a["start"], z["end"], round(a["start"] * FPS), sec_at(a["start"]), " ".join(Ws[q]["w"] for q in range(hit[0], hit[-1] + 1)), "all words heard" if full else "partial (%d of %d words)" % (len(hit), len(phrase.split()))))
    else:
        li = [i for i, L in enumerate(Ls) if linekey.lower() in L["text"].lower()]
        ws_ = [w for w in Ws if w["line"] in li]
        if ws_: o.append("| %s | %.2f | %.2f | %d | %s | %s | **not heard as written**; nearest anchor = the line's matched word(s) |" % (label, ws_[0]["start"], ws_[-1]["end"], round(ws_[0]["start"] * FPS), sec_at(ws_[0]["start"]), " ".join(w["w"] for w in ws_)))
        else: o.append("| %s | - | - | - | - | - | **not found**; no matched word |" % label)
nerf = [L for L in Ls if L["text"].upper().startswith("NERFED") and L["start"] is not None]
for L in nerf: o.append("| NERFED! (line start) | %.2f | - | %d | %s | %s | line anchored; first heard word is the NERFED! hit |" % (L["start"], round(L["start"] * FPS), L["section"], L["heard"].split(" ")[0] + " " + L["heard"].split(" ")[1] if len(L["heard"].split(" ")) > 1 else L["heard"]))
vo = [w for w in Ws if sim(norm(w["w"]), "vorathul") >= 0.8 and w["start"] > 248.0]
vg = [w for w in Ws if w["start"] > 240 and (norm(w["w"]).startswith("vra") or "tull" in norm(w["w"]))]
for w in vo: o.append("| VO-RA-THUL (choir, exact word) | %.2f | %.2f | %d | %s | %s | source: %s |" % (w["start"], w["end"], round(w["start"] * FPS), sec_at(w["start"]), w["w"], w["source"]))
o.append("| VO-RA-THUL (choir, garbled words) | %s | %s | - | Choir | %s | the mix pass heard the chant as 'Våra Tull'; these are word starts |" % (", ".join("%.1f" % w["start"] for w in vg), "-", " ".join(w["w"] for w in vg)))
o.append("")
o.append("Announcer words are measured on the robot voice; whisper heard 'Voratho's' for 'Vorathul's' in Announcer 2 and 'Vorathul' (with 'For a fool') for 'Vorathul: changes reverted' in Announcer 3. For 'changes reverted' the nearest measured anchor is the 'Patch two point five' line plus the 'Vorathul' word, shown above. Whisper's first word after a rest can be early or late by up to ~1 s ('Patch' in Announcer 1 is heard at 77.8 s by the mix pass and 79.1 s by the vocal-stem pass).\n")

# ---- key
o.append("## Key\n")
o.append("Krumhansl-Schmuckler on harmonic chroma per section (the music is heavily distorted and modal, so the mode and tonic flip between relative pairs such as E minor / G major and B minor / D major; read r < 0.7 as 'unsettled'):\n")
o.append("| section | best key (r) | second (r) |"); o.append("|---|---|---|")
for k in T["key_per_section"]: o.append("| %s | %s (%.2f) | %s (%.2f) |" % (k["section"], k["best"], k["r"], k["second"], k["r2"]))
sh = T["key_shift_between_choruses"]; bs = T["chorus_bar_by_bar_shift"]
o.append("\n**Final-chorus key change up: not detected.** Whole-chorus chroma correlation at shift 0 vs the best shift: Chorus 1 vs Chorus 2 %.2f/%.2f, Chorus 2 vs Final Chorus %.2f/%.2f (best shift %d semitones); a +2 shift would score %.2f. Bar by bar on the accompaniment stem (bar i of one chorus vs bar i of the other): Chorus 1 vs 2 has shift 0 in %d of %d bars, Chorus 2 vs Final in %d of %d (the exceptions are the first and last bar of the chorus, which overlap the transitions), Chorus 1 vs Final in %d of %d. The final chorus therefore uses the same pitch classes as the earlier ones. The listening model claims a modulation of about +2 semitones at 3:44; that is not supported by the chroma. A shift of the lead vocal alone (melody raised, backing unchanged) was **not measured** (the pitch tracker failed on the layered vocals).\n" % (
    sh["Chorus1_vs_Chorus2"]["r_at_zero"], sh["Chorus1_vs_Chorus2"]["r_at_best"], sh["Chorus2_vs_FinalChorus"]["r_at_zero"], sh["Chorus2_vs_FinalChorus"]["r_at_best"], sh["Chorus2_vs_FinalChorus"]["best_shift_semitones"], sh["Chorus2_vs_FinalChorus"]["r_by_shift_0_to_11"][2],
    bs["Chorus1_vs_Chorus2"]["bars_with_shift_0"], bs["Chorus1_vs_Chorus2"]["n"], bs["Chorus2_vs_FinalChorus"]["bars_with_shift_0"], bs["Chorus2_vs_FinalChorus"]["n"], bs["Chorus1_vs_FinalChorus"]["bars_with_shift_0"], bs["Chorus1_vs_FinalChorus"]["n"]))

# ---- loudness
o.append("## Loudest, biggest hits, quietest\n")
o.append("Loudest 10 bars (RMS of the mix, dB; the whole song is heavily compressed, loud bars are within %.1f dB of each other):\n" % (T["loudest_bars"][0]["db"] - T["loudest_bars"][-1]["db"]))
o.append("| rank | bar | start | dB | section |"); o.append("|---|---|---|---|---|")
for i, b in enumerate(T["loudest_bars"]): o.append("| %d | %d | %s | %.2f | %s |" % (i + 1, b["bar"], ts(b["start"]), b["db"], b["section"]))
o.append("\nBiggest 10 onsets (`hits[]`, onset strength relative to the strongest; snapped = within 1 frame of a grid beat). Onset strength is relative to the surroundings, so hits right after the near-silence and at announcer starts outrank hits inside the loud choruses:\n")
o.append("| rank | t | strength | band | beat | dt ms | section |"); o.append("|---|---|---|---|---|---|---|")
for i, h in enumerate(sorted(T["hits"], key=lambda h: -h["strength"])[:10]): o.append("| %d | %s (%.2f s) | %.2f | %s | %s | %+.0f | %s |" % (i + 1, ts(h["t"]), h["t"], h["strength"], h["dominant_band"], h["beat_idx"] if h["beat_idx"] is not None else "-", h["dt_ms"], sec_at(h["t"])))
q = T["quietest_4_bar_stretch"]; pi = next(s for s in S if s["name"] == "Soft Interlude")
_ib = [b for b in T["bars"] if pi["start"] - 0.01 <= b["start"] < pi["end"] - 0.01]
_w = [(sum(x["mean_db"] for x in _ib[i:i + 4]) / 4, _ib[i]["start"], _ib[i + 3]["end"]) for i in range(len(_ib) - 3)]; _m = min(_w)
qi = dict(db=_m[0], start=_m[1], end=_m[2])
o.append("\nQuietest 4-bar stretch of the whole file: %s - %s, mean %.1f dB, inside %s - that is the Announcer 1 reading, **not the piano interlude**. The Soft Interlude (%s - %s) has mean %.1f dB (min bar %.1f dB; band stem %.1f dB), only %.1f dB under the verse/chorus level: this song is so compressed that the 'tender piano' is not much quieter in RMS terms. Quietest 4-bar stretch inside the interlude: %s - %s, mean %.1f dB." % (
    ts(q["start"]), ts(q["end"]), q["mean_db"], sec_at(q["start"]), ts(pi["start"]), ts(pi["end"]), pi["mean_db"], pi["min_bar_db"], pi["mean_band_db"], next(s for s in S if s["name"] == "Chorus 2")["mean_db"] - pi["mean_db"], ts(qi["start"]), ts(qi["end"]), qi["db"]))
o.append("Section means (dB, mix): " + ", ".join("%s %.1f" % (s["name"], s["mean_db"]) for s in S) + ".\n")

# ---- not measured
o.append("## NOT measured / uncertain\n")
for x in [
    "Growl vs operatic vs scream vs laughter vs 'robot' as voice types: only the sheet's tags are carried (pitch tracking on the vocal stem failed for most lines: %d of %d lines have an f0 median, none in the growl lines)." % (sum(L["f0_median_hz"] is not None for L in Ls), len(Ls)),
    "Instrumentation per section (organ, harpsichord, piano, choir): not measured by code; only the listening notes (a model's opinion) speak to it.",
    "Whether the final chorus is raised in the lead vocal only: not measured. Only the accompaniment/mix chroma was compared (no change).",
    "Bar lines: the downbeat choice is weak (see Tempo and grid); beat positions are better than bar numbers. Odd bars (2, 3, 5, 6 beats) at the listed times are the tracker's way of absorbing tempo changes, not a measured change of meter.",
    "Tempo in Announcer 1 and 2 (79-93 s, 137-147 s) is fitted on few weak onsets; interlude/build 171.7-197.2 s is the firm slowdown; 243-274 s (181.6 BPM) is moderately supported.",
    "The robot announcer: the stems cannot confirm 'robot'; what is measured is the level drop of the band (10-14 dB under the song's median over the announcer sections) while speech continues. A total cut exists only at 78.3-78.8 s.",
    "Whisper word times for the first word after a rest can be off by up to ~1 s; line starts are good to ~0.3 s, not to the frame. Use beats and `hits[]` for frame-exact sync.",
    "The Intro's 'Vo-ra-thul' chants: only 2 (3.5 s and 12.1 s) were heard by whisper; the choir may chant more often.",
    "Outro: the last section (laughter, final organ chord) is only %s - %s here, found by an energy step (%.1f dB) after the last heard word; laughter is not detected by any tool, only by the listening model, which places it before the final VO-RA-THUL choir." % (ts(S[-1]["start"]), ts(S[-1]["end"]), float(re.search(r"-?\d+\.\d", S[-1]["start_rule"]).group())),
    "Key per section is template-based (Krumhansl-Schmuckler) and unstable (r mostly 0.5-0.8); tonic and mode are not reliable, only the relative sameness of the choruses is."]:
    o.append("- " + x)
open(R + "timing-summary.md", "w", encoding="utf-8").write("\n".join(o) + "\n")
print("written", len(o), "blocks")
